window.ScripturaLexicons.BDAG_PART_0023 = {source:"BDAG", searchAnchorId:"bdag-search-anchor", entryAnchorId:"bdag-entry-anchor", rowsHtml:"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hallomai-bdag\" data-source=\"BDAG\" data-search=\"ἅλλομαι hallomai saltar pular jorrar brotar água BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλλομαι</td><td>Verbo</td><td>saltar; brotar; jorrar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allos-bdag\" data-source=\"BDAG\" data-search=\"ἄλλος allos outro outros diferente adicional mais restante BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλλος</td><td>Adjetivo / pronome</td><td>outro; diferente; mais</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allotriepiskopos-bdag\" data-source=\"BDAG\" data-search=\"ἀλλοτριεπίσκοπος allotriepiskopos sentido incerto intrometido delator informante revolucionário 1 Pedro 4 BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλοτριεπίσκοπος</td><td>Substantivo</td><td>sentido incerto</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allotrios-bdag\" data-source=\"BDAG\" data-search=\"ἀλλότριος allotrios alheio estranho estrangeiro outro inimigo hostil BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλότριος</td><td>Adjetivo / substantivo</td><td>alheio; estranho; estrangeiro; inimigo</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allophylos-bdag\" data-source=\"BDAG\" data-search=\"ἀλλόφυλος allophylos estrangeiro gentio forasteiro filisteu amalequita cananeu BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλλόφυλος</td><td>Adjetivo / substantivo</td><td>estrangeiro; gentio; forasteiro</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-allos-adv-bdag\" data-source=\"BDAG\" data-search=\"ἄλλως allos de outro modo de outra maneira caso contrário BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλλως</td><td>Advérbio</td><td>de outro modo; de outra maneira</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aloao-bdag\" data-source=\"BDAG\" data-search=\"ἀλοάω aloao debulhar trilhar grão eira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλοάω</td><td>Verbo</td><td>debulhar; trilhar</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alogos-bdag\" data-source=\"BDAG\" data-search=\"ἄλογος alogos irracional sem razão absurdo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλογος</td><td>Adjetivo</td><td>irracional; contrário à razão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-aloe-bdag\" data-source=\"BDAG\" data-search=\"ἀλόη aloe aloés planta aromática embalsamamento mirra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλόη</td><td>Substantivo feminino</td><td>aloés</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hals-bdag\" data-source=\"BDAG\" data-search=\"ἅλς hals sal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλς</td><td>Substantivo masculino</td><td>sal</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halykos-bdag\" data-source=\"BDAG\" data-search=\"ἁλυκός halykos salgado água salgada fonte salgada BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἁλυκός</td><td>Adjetivo</td><td>salgado</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alypetos-bdag\" data-source=\"BDAG\" data-search=\"ἀλύπητος alypētos sem tristeza livre de tristeza BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλύπητος</td><td>Adjetivo</td><td>sem tristeza</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alypos-bdag\" data-source=\"BDAG\" data-search=\"ἄλυπος alypos sem ansiedade livre de ansiedade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλυπος</td><td>Adjetivo</td><td>livre de ansiedade</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halysis-bdag\" data-source=\"BDAG\" data-search=\"ἅλυσις halysis cadeia corrente algemas prisão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἅλυσις</td><td>Substantivo feminino</td><td>cadeia; algemas; prisão</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alysiteles-bdag\" data-source=\"BDAG\" data-search=\"ἀλυσιτελής alusiteles improdutivo sem proveito prejudicial nocivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἀλυσιτελής</td><td>Adjetivo</td><td>sem proveito; prejudicial</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-alpha-word-bdag\" data-source=\"BDAG\" data-search=\"ἄλφα alpha alfa letra grega primeira letra BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἄλφα</td><td>Substantivo neutro indeclinável</td><td>alfa</td><td><span class=\"source-pill\">BDAG</span></td></tr><tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-halphaios-bdag\" data-source=\"BDAG\" data-search=\"Ἁλφαῖος Halphaîos Alfeu pai Levi cobrador impostos pai Tiago doze discípulos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Ἁλφαῖος</td><td>Nome próprio masculino</td><td>Alfeu</td><td><span class=\"source-pill\">BDAG</span></td></tr>", cardsHtml:"<article id=\"entry-hallomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλλομαι</h1><div class=\"entry-meta\"><span class=\"greek\">fut. ἁλούμαι; 1 aor. ἡλάμην</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hállomai⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλούμαι\" data-meanings=\"saltarei\">ἁλούμαι</span>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡλάμην\" data-meanings=\"saltei\">ἡλάμην</span> (Homero e outros; LXX; Jos., <em>Bell.</em> 5, 330, <em>Ant.</em> 20, 61; Just., <em>D.</em> 69, 6 [veja <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.35.6\" target=\"_blank\" rel=\"noopener noreferrer\">Is 35.6</a>]).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Literalmente, <strong>fazer um movimento rápido de salto: saltar, pular</strong> (PRyl 138, 15). Do coxo depois de curado (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.35.6\" target=\"_blank\" rel=\"noopener noreferrer\">Is 35.6</a>): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"περιπατῶν καὶ ἁλλόμενος\" data-meanings=\"andando e saltando\">περιπατῶν καὶ ἁλλόμενος</span>, <strong>andando e saltando</strong>, isto é, mostrando por movimentos lentos e rápidos que estava realmente curado, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 3.8</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἥλατο καὶ περιεπάτει\" data-meanings=\"saltou e começou a andar\">ἥλατο καὶ περιεπάτει</span>, <strong>saltou e pôde andar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.10\" target=\"_blank\" rel=\"noopener noreferrer\">14.10</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Figuradamente, do movimento rápido de coisas inanimadas (desde <em>Il.</em> 4, 125, de uma flecha): <strong>brotar de uma fonte</strong>; da água, <strong>jorrar, brotar</strong> (como lat. <em>salire</em>, Virgílio, <em>Ecl.</em> 5, 47; Suetônio, <em>Octav.</em> 82): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πηγὴ ὕδατος ἁλλομένου\" data-meanings=\"uma fonte de água que jorra\">πηγὴ ὕδατος ἁλλομένου</span>, <strong>uma fonte de água que jorra</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.14</a>. — DELG. M-M.</p>\n</section></article><article id=\"entry-allos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλλος</h1><div class=\"entry-meta\"><span class=\"greek\">η, ο</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦állos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Homero+.) <span class=\"sense-number\">1.</span> <strong>Relativo àquilo que é outro em relação a alguma outra entidade: outro.</strong> <strong>a.</strong> Distinto do sujeito que fala ou que é logicamente pressuposto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μήπως ἄλλοις κηρύξας αὐτὸς ἀδόκιμος γένωμαι\" data-meanings=\"para que, tendo pregado a outros, eu mesmo não venha a ser desqualificado\">μήπως ἄλλοις κηρύξας αὐτὸς ἀδόκιμος γένωμαι</span>, <strong>para que, depois de pregar a outros, eu mesmo não venha a ser desqualificado</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.27\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.27</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος ἐστὶν ὁ μαρτυρῶν\" data-meanings=\"outro é aquele que dá testemunho\">ἄ. ἐστὶν ὁ μαρτυρῶν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.32\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5.32</a> (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span> de Deus, como Epicteto 3, 13, 13). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλη συνείδησις\" data-meanings=\"consciência de outro\">ἄλλη συνείδησις</span> (= <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλου συνείδησις\" data-meanings=\"consciência de outro\">ἄλλου συν.</span>), <strong>os escrúpulos de consciência de outro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.29\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10.29</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλους ἔσωσεν, ἑαυτὸν οὐ δύναται σῶσαι\" data-meanings=\"salvou outros; a si mesmo não pode salvar\">ἄλλους ἔσωσεν, ἑαυτὸν οὐ δύναται σῶσαι</span>, <strong>salvou outros; a si mesmo não pode salvar</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27.42</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 15.31</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.23.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 23.35</a>.</p>\n<p class=\"entry-text\"><strong>b.</strong> Distinto de: <strong>α.</strong> Um sujeito ou objeto anteriormente mencionado: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλα δὲ ἔπεσεν\" data-meanings=\"outras [sementes] caíram\">ἄλλα δὲ ἔπεσεν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13.5</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">7s.</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλην παραβολήν\" data-meanings=\"outra parábola\">ἄλλην παραβολήν</span>, vv. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">24</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.31\" target=\"_blank\" rel=\"noopener noreferrer\">31</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.33\" target=\"_blank\" rel=\"noopener noreferrer\">33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">21.33</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλους ἑστῶτας\" data-meanings=\"outros que estavam em pé\">ἄλλους ἑστῶτας</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">20.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>. Frequentemente o sujeito ou objeto não é expresso, mas pode ser suprido do contexto: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δι’ ἄλλης ὁδοῦ ἀνεχώρησαν\" data-meanings=\"retiraram-se por outro caminho\">δι’ ἄλλης ὁδοῦ ἀνεχώρησαν</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2.12</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1KI.13.10\" target=\"_blank\" rel=\"noopener noreferrer\">3 Km 13.10</a>) e outros.</p>\n<p class=\"entry-text\"><strong>β.</strong> Diferente do sujeito numa frase contrastante seguinte: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλοι κεκοπιάκασιν, καὶ ὑμεῖς εἰς τὸν κόπον αὐτῶν εἰσεληλύθατε\" data-meanings=\"outros trabalharam, e vós entrastes no trabalho deles\">ἄλλοι κεκοπιάκασιν, καὶ ὑμεῖς εἰς τὸν κόπον αὐτῶν εἰσεληλύθατε</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.38</a> (J. A. T. Robinson, TU 73, 1959, 510–515 [identidade]).</p>\n<p class=\"entry-text\"><strong>c.</strong> Usado correlativamente em contraste: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ μὲν … ἄλλοι δέ\" data-meanings=\"uns … outros\">οἱ μὲν … ἄλλοι (δέ)</span>, <strong>uns … outros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 7.12</a>. Indefinido, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τινὲς … ἄλλοι\" data-meanings=\"alguns … outros\">τινὲς … ἄλλοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.16\" target=\"_blank\" rel=\"noopener noreferrer\">9.16</a>. Também <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ὄχλος … ἄλλοι\" data-meanings=\"a multidão … outros\">ὁ ὄχλος … ἄλλοι</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">12.29</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ πλεῖστος ὄχλος … ἄλλοι δέ\" data-meanings=\"a maior parte da multidão … outros, porém\">ὁ πλεῖστος ὄχλος … ἄλλοι δέ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21.8</a>. Sem menção do primeiro grupo, com os demais introduzidos por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλοι … ἄλλοι\" data-meanings=\"outros … outros\">ἄλλοι … ἄλλοι</span>: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">8.28</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.19\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9.19</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 9.9</a>.</p>\n<p class=\"entry-text\">Em enumerações, com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ μέν\" data-meanings=\"um\">ὁ μέν</span> no primeiro membro e continuação por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος δέ\" data-meanings=\"outro, porém\">ἄλλος δέ</span> (às vezes <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕτερος\" data-meanings=\"outro\">ἕτερος</span> ocupa o lugar de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>: Libânio, <em>Or.</em> 32, p. 155, 18 F. <span class=\"greek\">ἄλλοι … ἕτεροι</span>; Ath. 26, 2; Ps.-Clem., <em>Hom.</em> 19, 9; UPZ 42, 32s. [162 a.C.]; veja 2 abaixo), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.12.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 12.8ss.</a> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ πέντε … ὁ εἷς … ὁ ἄλλος\" data-meanings=\"os cinco … um … o outro, isto é, o último\">οἱ πέντε … ὁ εἷς … ὁ ἄλλος</span> = <strong>o último</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 17.10</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἄλλοι\" data-meanings=\"os outros; o restante\">οἱ ἄλλοι</span>, com substantivo expresso ou subentendido (Xenofonte, <em>Cyr.</em> 3, 3, 4; Herodiano 2, 4, 4), <strong>os outros, o restante</strong> (Ps.-Calístenes 3, 35 <span class=\"greek\">τὰ ἄλλα λ’ [ἔτη]</span> = “o restante dos trinta anos”), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.25\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 20.25</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">21.8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.29\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14.29</a>; AcPlCor 1:4; <span class=\"greek\">τὰ ἄλλα θηρία</span>, AcPl Ha 5, 9; <span class=\"greek\">τῶν ἄλλων σπερμάτων</span>, AcPlCor 2:26.</p>\n<p class=\"entry-text\">Vários casos de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span> em justaposição (índice de Epicteto em Schenkl; Hipócrates, <em>Ep.</em> 17, 31 <span class=\"greek\">ἀλλὰ ἄλλος ἄλλου</span>; Máximo de Tiro 3, 1d <span class=\"greek\">ἀλλὰ ἄλλον ἄλλο</span>; 21, 7b; Salústio 4 p. 6, 19; Jos., <em>Bell.</em> 7, 389; 396, <em>Ant.</em> 7, 325; Ath. 1, 1 e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος πρὸς ἄλλον λέγοντες\" data-meanings=\"dizendo um ao outro\">ἄ. πρὸς ἄ. λέγοντες</span>, <strong>um dizia ao outro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">At 2.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλοι μὲν οὖν ἄλλο τι ἔκραζον\" data-meanings=\"uns gritavam uma coisa, outros outra\">ἄλλοι μὲν οὖν ἄλλο τι ἔκραζον</span>, <strong>uns gritavam uma coisa, outros outra</strong> (Xenofonte, <em>An.</em> 2, 1, 15 <span class=\"greek\">ἄλλος ἄλλα λέγει</span>; Nicolau de Damasco: 90 Fgm. 130, 25 p. 409, 25 Jac. <span class=\"greek\">ἄλλοι δὲ ἄλλα ὑπελάμβανον</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">19.32</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.34\" target=\"_blank\" rel=\"noopener noreferrer\">21.34</a>.</p>\n<p class=\"entry-text\"><strong>d.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος τις\" data-meanings=\"algum outro; qualquer outro\">ἄλλος τις</span>, <strong>algum outro, qualquer outro</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μήτε ἄλλον τινὰ ὅρκον\" data-meanings=\"nem qualquer outro juramento\">μήτε ἄλλον τινὰ ὅρκον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.12\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 5.12</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος τις διϊσχυρίζετο\" data-meanings=\"outro homem afirmava com insistência\">ἄ. τις διϊσχυρίζετο</span>, <strong>outro homem afirmava</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22.59</a>. <span class=\"greek\">εἰ δέ τι ἄλλο παραδέχεσθε</span>, AcPlCor 2:34. Especialmente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἴ τις ἄλλος\" data-meanings=\"se algum outro\">εἴ τις ἄ.</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.13.39\" target=\"_blank\" rel=\"noopener noreferrer\">1Mac 13.39</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 1.16</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 3.4</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδεὶς ἄλλος\" data-meanings=\"ninguém mais\">οὐδεὶς ἄλλος</span>, <strong>ninguém mais</strong> (compare Jos., <em>Vi.</em> 196), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 15.24</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo ao que difere em tipo ou espécie de outras entidades, em comparações: outro, diferente (de, comparado com).</strong> <strong>a.</strong> Diferente em espécie, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.39\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 15.39ss.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 11.4</a> (alternando com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕτερος\" data-meanings=\"outro; diferente\">ἕτερος</span>; veja b abaixo, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.7</a>, e 1c acima; compare B-D-F §306).</p>\n<p class=\"entry-text\"><strong>b.</strong> <strong>Outro (exceto, além de).</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐκ ἔστιν ἄλλος πλὴν αὐτοῦ\" data-meanings=\"não há outro além dele\">οὐκ ἔστιν ἄ. πλὴν αὐτοῦ</span>, <strong>não há nenhum outro (Deus) além dele</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.32\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 12.32</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 8.6</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/ISA.45.21\" target=\"_blank\" rel=\"noopener noreferrer\">Is 45.21</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 7.1a</a>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὅτι … εἷς Χριστὸς Ἰησοῦς καὶ ἄλλος οὐχ ὑπάρχει\" data-meanings=\"que há um só Messias, Jesus, e não existe outro\">ὅτι … εἷς Χριστὸς Ἰησοῦς καὶ ἄ. οὐχ ὑπάρχει</span>, <strong>que há um só Messias, Jesus, e não haverá outro</strong>, AcPl Ha 1, 18. Com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλά\" data-meanings=\"mas\">ἀλλά</span> a seguir, 1 Cl 51:5; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλ’ ἤ\" data-meanings=\"senão; exceto\">ἀλλ’ ἤ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 1.13</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εἰ μή\" data-meanings=\"senão; exceto\">εἰ μή</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 6.22</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρά\" data-meanings=\"além de; em comparação com\">παρά</span> com acusativo (Filóstrato, <em>Vi. Apoll.</em> 5, 30 p. 188, 30; Just., <em>A I</em> 19, 5; 58, 1), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 3.11</a>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.1.6\" target=\"_blank\" rel=\"noopener noreferrer\">Gl 1.6–7</a> (B-D-F §306, 4; Mlt. 80 n. 1; 246; E. Burton, <em>ICC Gal.</em>, 420–422) pertence a esta seção (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕτερος\" data-meanings=\"outro\">ἕτερος</span> 1bγ).</p>\n<p class=\"entry-text\"><strong>c.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος ἐστὶν ὁ σπείρων καὶ ἄλλος ὁ θερίζων\" data-meanings=\"um é o que semeia e outro o que ceifa\">ἄλλος ἐστὶν ὁ σπείρων καὶ ἄλλος ὁ θερίζων</span>, <strong>um semeia, outro ceifa</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.37\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4.37</a>. <strong>d.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος καὶ ἄλλος\" data-meanings=\"cada um diferente; simplesmente diferente\">ἄλλος καὶ ἄλλος</span>, <strong>cada um diferente</strong>, ou simplesmente <strong>diferente</strong> (Apiano, <em>Iber.</em> 62 §260), Hs 9, 1, 4; 10; 9, 17, 1; 2; 9, 28, 1.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Relativo a estar em adição: mais</strong> (Platão, <em>Leg.</em> 5, 745a <span class=\"greek\">ἄλλο τοσοῦτον μέρος</span>), com numerais cardinais (Estêvão de Bizâncio s.v. <span class=\"greek\">Ἐορδαῖαι</span>: <span class=\"greek\">ἄλλαι δύο χῶραι</span>; Diógenes Laércio 1, 115 <span class=\"greek\">Ἐπιμενίδαι ἄλλοι δύο</span>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.41.3\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 41.3</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.41.6\" target=\"_blank\" rel=\"noopener noreferrer\">6</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.41.23\" target=\"_blank\" rel=\"noopener noreferrer\">23</a>; Jos., <em>Ant.</em> 1, 92): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλους δύο ἀδελφούς\" data-meanings=\"mais dois irmãos\">ἄ. δύο ἀδελφούς</span>, <strong>mais dois irmãos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4.21</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλα πέντε τάλαντα\" data-meanings=\"mais cinco talentos\">ἄ. πέντε τάλαντα</span> (compare SIG 201, 17 [356 a.C.] <span class=\"greek\">ἄλλας τριάκοντα μνᾶς</span>; PBour 23, 7 [séc. II d.C.]; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1ES.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">1Esd 4.52</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.15.31\" target=\"_blank\" rel=\"noopener noreferrer\">1Mac 15.31</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.20\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25.20</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.22\" target=\"_blank\" rel=\"noopener noreferrer\">22</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"μετ’ αὐτοῦ ἄλλοι δύο\" data-meanings=\"com ele mais dois\">μετ’ αὐτοῦ ἄ. δύο</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.18</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">4.</span> <strong>Com artigo, relativo a ser o restante de dois ou mais: o outro dos dois</strong> (Sófocles, <em>El.</em> 739; Eurípides, <em>Iph. T.</em> 962s.; Platão, <em>Leg.</em> 1, 629d; SIG 736, 91 [92 a.C.]; UPZ 162 VIII, 34 [117 a.C.]; BGU 456, 10ss.; CPR 22, 15 [séc. II d.C.] <span class=\"greek\">τὸ ἄλλο ἥμισυ</span>; também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/TOB.8.21\" target=\"_blank\" rel=\"noopener noreferrer\">Tb 8.21</a> S; compare também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1SA.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">1 Km 14.4</a>. A palavra estritamente correta seria <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἕτερος\" data-meanings=\"o outro de dois\">ἕτερος</span>. TestJob 9:8): a mão curada é <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὑγιὴς ὡς ἡ ἄλλη\" data-meanings=\"sã como a outra\">ὑγιὴς ὡς ἡ ἄλλη</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12.13</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ ἄλλη Μαρία\" data-meanings=\"a outra Maria\">ἡ ἄ. Μαρία</span>, para distingui-la de Maria Madalena (como Apiano, <em>Basil.</em> 1a §4 <span class=\"greek\">Αἰνείας ἄλλος</span>; Arriano, <em>Anab.</em> 5, 21, 3; 5 <span class=\"greek\">ὁ ἄλλος Πῶρος</span>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.61\" target=\"_blank\" rel=\"noopener noreferrer\">27.61</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.28.1\" target=\"_blank\" rel=\"noopener noreferrer\">28.1</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"στρέψον αὐτῷ καὶ τὴν ἄλλην\" data-meanings=\"volta-lhe também a outra\">στρέψον αὐτῷ καὶ τὴν ἄ.</span>, <strong>volta-lhe também a outra</strong> (isto é, a face esquerda), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.39\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5.39</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.29</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ μαθητὴς ὁ ἄλλος\" data-meanings=\"o outro discípulo\">ὁ μαθητὴς ὁ ἄλλος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.16\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18.16</a> (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.20.2\" target=\"_blank\" rel=\"noopener noreferrer\">20.2ss.</a>); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τοῦ ἄλλου τοῦ συσταυρωθέντος\" data-meanings=\"do outro que foi crucificado com ele\">τοῦ ἄ. τοῦ συσταυρωθέντος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.32\" target=\"_blank\" rel=\"noopener noreferrer\">19.32</a>. — Veja o advérbio <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλως\" data-meanings=\"de outro modo\">ἄλλως</span>. DELG. M-M. TW. Sv.</p>\n</section></article><article id=\"entry-allotriepiskopos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλοτριεπίσκοπος</h1><div class=\"entry-meta\"><span class=\"greek\">v.l. ἀλλοτριοεπίσκοπος; ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allotriepískopos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Variante <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοτριοεπίσκοπος\" data-meanings=\"forma variante de ἀλλοτριεπίσκοπος\">ἀλλοτριοεπίσκοπος</span>; veja Mlt-H. 272; B-D-F §124), <span class=\"greek\">ου, ὁ</span>. Em outro lugar apenas Dionísio Areopagita, <em>Ep.</em> 8: MPG III 1089c, <span class=\"greek\">ἀλλοτριοεπίσκοπος</span>; compare Epifânio de Constância (Salamina), <em>Ancoratus</em> 12; veja Lampe s.v. <strong>Palavra cujo significado ainda não foi determinado com certeza</strong>; ocorre com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"φονεύς\" data-meanings=\"homicida\">φονεύς</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλέπτης\" data-meanings=\"ladrão\">κλέπτης</span>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κακοποιός\" data-meanings=\"malfeitor\">κακοποιός</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.15</a>.</p>\n<p class=\"entry-text\">E. Zeller, SBBerlAk 1893, 129ss., referindo-se à pretensão dos pregadores cínicos de serem supervisores (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐπίσκοποι\" data-meanings=\"supervisores; inspetores\">ἐπίσκοποι</span>) de todos os seres humanos (Epicteto 3, 22, 97 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐ τὰ ἀλλότρια πολυπραγμονεῖ ὅταν τὰ ἀνθρώπινα ἐπισκοπῇ ἀλλὰ τὰ ἴδια\" data-meanings=\"não se ocupa do que é alheio quando supervisiona as coisas humanas, mas do que lhe é próprio\">οὐ τὰ ἀλλότρια πολυπραγμονεῖ ὅταν τὰ ἀνθρώπινα ἐπισκοπῇ ἀλλὰ τὰ ἴδια</span>), interpreta a palavra como significando <strong>alguém que se intromete em assuntos que não lhe dizem respeito, um intrometido</strong> (semelhantemente REB; NRSV: “mischief maker”; veja P. Wendland, <em>Kultur</em><sup>2</sup> 1912, 82, 1; Zahn, <em>Einl.</em> II 39s.; E. Selwyn, <em>Comm.</em> 1946 ad loc. Compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοτρίοις ἐπίσκοπος\" data-meanings=\"supervisor dos assuntos de outros; intrometido nos assuntos alheios\">ἀλλοτρίοις ἐπίσκοπος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.15</a> P72, “intrometendo-se nos assuntos de outras pessoas” = lat. <em>alienis custos</em>.)</p>\n<p class=\"entry-text\">Mas é questionável se tal comportamento mereceria o tipo de represália sugerido pelo contexto. Por isso se propôs um tipo de crime mais grave, e a proximidade de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κλέπτης\" data-meanings=\"ladrão\">κλέπτης</span> levou à conjectura <strong>receptador de bens roubados</strong>. Para <strong>espião, informante</strong> (lat. <em>delator</em>), veja A. Hilgenfeld, <em>Einl.</em> 1875, 630. Dssm., NB 51, 5 = BS 224, 4 (BGU 531 II, 22 [séc. II d.C.] <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὔτε εἰμὶ ἄδικος οὔτε ἀλλοτρίων ἐπιθυμητής\" data-meanings=\"não sou injusto nem cobiçador das coisas alheias\">οὔτε εἰμὶ ἄδικος οὔτε ἀλλοτρίων ἐπιθυμητής</span>) sugere <strong>revolucionário</strong> (veja A. Bischoff, ZNW 7, 1906, 271–274; 9, 1908, 171; P. Schmidt, ZWT 50, 1908, 26ss.). K. Erbes, ZNW 19, 1920, 39–44; 20, 1921, 249, considera-o uma criação cristã dirigida contra bispos negligentes. Tertuliano, <em>Scorp.</em> 12: <em>alieni speculator</em>. Cipriano, <em>Test.</em> 3, 37: <em>curas alienas agens</em>. Vulgata: <em>alienorum adpetitor</em>. — J. Bauer, BZ n.s. 22, 1978, 109–115. — DELG. M-M. TW.</p>\n</section></article><article id=\"entry-allotrios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλότριος</h1><div class=\"entry-meta\"><span class=\"greek\">ία, ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allótrios⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(De <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>; Homero+; DELG I 64 s.v. <span class=\"greek\">ἄλλος</span>.) <span class=\"sense-number\">1.</span> <strong>Relativo ao que pertence a outro, não ao próprio: alheio, estranho</strong> (em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἴδιος\" data-meanings=\"próprio\">ἴδιος</span>; <em>Περὶ ὕψους</em> 4, 1; Epicteto 2, 4, 10; 3, 24, 3s.; <em>Proverb. Aesopi</em> 114 P.; SIG 982, 5s.; papiros desde o séc. III a.C., por exemplo BGU 1121, 22 [5 a.C.] <span class=\"greek\">μήτε ἴδια μήτ’ ἀλλότρια</span>; 15, 15; Jos., <em>Ant.</em> 18, 46; 19, 305).</p>\n<p class=\"entry-text\"><strong>a.</strong> Adjetivo: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλότριος οἰκέτης\" data-meanings=\"servo de outro\">ἀ. οἰκέτης</span>, <strong>servo de outro</strong> (Dio Crisóstomo 14 [31], 34 <span class=\"greek\">ἀλλ. οἰκ.</span>; Jos., <em>Ant.</em> 18, 47; <span class=\"greek\">ἀ. δοῦλος</span> já em Platão, <em>Leg.</em> 9, 9, 868a; compare Diod S 36, 2, 2), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.14.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 14.4</a>; <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"γυνὴ ἀλλοτρία\" data-meanings=\"mulher de outro\">γυνὴ ἀ.</span> (Cáriton 6, 3, 7; POxy 1067, 6ss.), Hm 4, 1, 1; 12, 2, 1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"καυχᾶσθαι ἐν ἀλλοτρίοις κόποις\" data-meanings=\"gloriar-se em trabalhos feitos por outros\">καυχᾶσθαι ἐν ἀ. κόποις</span>, <strong>gloriar-se em trabalho feito por outros</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.15\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10.15</a> (compare Epicteto 1, 28, 23 <span class=\"greek\">ἀλλότριον ἔργον</span> = “feito de outro”; Taciano 26, 1 <span class=\"greek\">λόγους ἀ.</span>, “palavras de outros”); <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κοινωνεῖν ἁμαρτίαις ἀλλοτρίαις\" data-meanings=\"participar dos pecados de outros\">κοινωνεῖν ἁμαρτίαις ἀ.</span>, <strong>participar dos pecados de outras pessoas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.22</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν ἀλλοτρίῳ κανόνι καυχᾶσθαι\" data-meanings=\"gloriar-se no campo de outro\">ἐν ἀ. κανόνι καυχᾶσθαι</span>, <strong>gloriar-se (de trabalho já realizado) no campo de outro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.10.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 10.16</a>. <span class=\"greek\">πάντα ἀ. εἰσι</span> (com <span class=\"greek\">ὑπ’ ἐξουσίαν ἑτέρου</span>), Hs 1:3. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλότριον αἷμα\" data-meanings=\"sangue alheio\">ἀ. αἷμα</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.9.25\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 9.25</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεμέλιον\" data-meanings=\"fundamento\">θεμέλιον</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.15.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 15.20</a>. <span class=\"greek\">ἀλλοτρίας σάρκας καταφαγεῖν</span>, B 10:4b. <span class=\"greek\">τὰς ἀ. ἐντολὰς</span> (em oposição a <span class=\"greek\">παρὰ τοῦ κυρίου δεδομένας</span>), Papias (2:3).</p>\n<p class=\"entry-text\">De terras (aretalogia de Ísis SEG VIII, 548, 31 [séc. I a.C.]), <strong>estrangeiro</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πάροικον ἐν γῇ ἀλλοτρίᾳ\" data-meanings=\"peregrino em terra estrangeira\">πάροικον ἐν γῇ ἀ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 7.6</a> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/EXO.2.22\" target=\"_blank\" rel=\"noopener noreferrer\">Êx 2.22</a>; ParJer 7:34). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παροικεῖν εἰς γῆν … ὡς ἀλλοτρίαν\" data-meanings=\"peregrinar numa terra como se fosse estrangeira\">παροικεῖν εἰς γῆν … ὡς ἀ.</span>, <strong>peregrinar numa terra como se fosse estrangeira</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.9\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.9</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλότριοι τοῦ θεοῦ\" data-meanings=\"estranhos a Deus; alheios a Deus\">ἀ. τοῦ θεοῦ ὄντες</span>, <strong>alheios a Deus</strong>, 1 Cl 7:7 (compare PsSol 17:13 <span class=\"greek\">ἀπὸ τοῦ θεοῦ</span>; Herm. Wr. 2, 16; Just., <em>D.</em> 8, 2 <span class=\"greek\">ἀλλοτρίῳ τοῦ πράγματος</span>; B-D-F §182, 3); assim, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ κοσμικὰ ὡς ἀλλότρια ἡγεῖσθαι\" data-meanings=\"considerar as coisas mundanas como alheias\">τὰ κοσμικὰ ὡς ἀ. ἡγεῖσθαι</span>, isto é, considerar as coisas mundanas como algo que não diz respeito aos cristãos, 2 Cl 5:6.</p>\n<p class=\"entry-text\"><strong>b.</strong> Como substantivo. <strong>α.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ ἀλλότριον\" data-meanings=\"a propriedade de outros; o que pertence a outro\">τὸ ἀ.</span>, <strong>a propriedade de outras pessoas</strong> (Epicteto 2, 6, 8; Jos., <em>C. Ap.</em> 2, 216), B 10:4a. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἐν τῷ ἀλλοτρίῳ πιστοί\" data-meanings=\"fiéis naquilo que pertence a outro\">ἐν τῷ ἀ. πιστοί</span>, <strong>fiéis naquilo que pertence a outro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 16.12</a> (a riqueza deste mundo é estranha ao cristão; compare Epicteto 4, 5, 15, sobre bens temporais: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὐδὲν ἴδιον τῷ ἀνθρώπῳ ἐστίν, ἀλλὰ πάντα ἀλλότρια\" data-meanings=\"nada é próprio do ser humano, mas tudo é alheio\">οὐδὲν ἴδιον τῷ ἀνθρώπῳ ἐστίν, ἀλλὰ πάντα ἀλλότρια</span>; também 2, 6, 8; 24. Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡμέτερος\" data-meanings=\"nosso\">ἡμέτερος</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοτρίοις ἐπίσκοπος\" data-meanings=\"supervisor dos assuntos alheios; intrometido\">ἀλλοτρίοις ἐπίσκοπος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 4.15</a> P72, “intrometendo-se nos assuntos de outras pessoas” = lat. <em>alienis custos</em>; mas veja o verbete anterior. <span class=\"greek\">τοῦ ἀ. ἅψασθαι</span>, Hs 1:11; <span class=\"greek\">ἀλλοτρίων ἐπιθυμεῖν</span>, ibid. (compare Ar. 15, 4 <span class=\"greek\">οὐκ ἐπιθυμοῦσι … τὰ ἀ.</span>).</p>\n<p class=\"entry-text\"><strong>β.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀλλότριος\" data-meanings=\"o estranho; o desconhecido\">ὁ ἀ.</span>, <strong>o estranho</strong> (= “alguém desconhecido”; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/SIR.8.18\" target=\"_blank\" rel=\"noopener noreferrer\">Sir 8.18</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10.5a</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ ἀλλότριοι\" data-meanings=\"pessoas estranhas; estrangeiros\">οἱ ἀλλότριοι</span>, <strong>pessoas estranhas</strong>, v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">5b</a>; especificamente <strong>estrangeiros</strong> (LXX; Jos., <em>Bell.</em> 7, 266), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17.25s.</a> (em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οἱ υἱοί\" data-meanings=\"os filhos\">οἱ υἱοί</span>).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo a estar fora da experiência ou prática costumeira de alguém: estranho, inadequado</strong> (compare UPZ 113, 11 [séc. II a.C.]; POxy 282, 9): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"στάσις ἀλλοτρία\" data-meanings=\"dissensão estranha; dissensão alheia\">στάσις ἀ.</span>, explicada por <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ξένη τοῖς ἐκλεκτοῖς τοῦ θεοῦ\" data-meanings=\"estranha aos eleitos de Deus\">ξένη τοῖς ἐκλεκτοῖς τοῦ θεοῦ</span>, 1 Cl 1:1. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλλοτρία γνώμη\" data-meanings=\"opinião estranha; falsa\">ἀ. γνώμη</span>, <strong>opinião estranha = falsa</strong> (compare <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"θεὸς ἀλλότριος\" data-meanings=\"deus estranho\">θεὸς ἀλλότριος</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.80.10\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 80.10</a>; ParJer 7:30), IPhld 3:3; <span class=\"greek\">ἀ. βοτάνη</span>, ITr 6:1; <span class=\"greek\">χρῶμα</span>, IRo inscr.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">3.</span> <strong>Relativo a ser diferente e, por isso, estar em oposição: hostil</strong>; como substantivo, <strong>inimigo</strong> (Homero e outros; Políbio 27, 15, 13; Diod S 11, 27 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.1.38\" target=\"_blank\" rel=\"noopener noreferrer\">1Mac 1.38</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/1MA.2.7\" target=\"_blank\" rel=\"noopener noreferrer\">2.7</a>; compare OGI 90, 91): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"παρεμβολὰς κλίνειν ἀλλοτρίων\" data-meanings=\"pôr em fuga exércitos de inimigos\">παρεμβολὰς κλίνειν ἀλλοτρίων</span>, <strong>pôr em fuga exércitos de inimigos</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11.34</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-allophylos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλλόφυλος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦allóphulos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Ésquilo, Tucídides e outros; BGU 34; 411; 419; 858; LXX; Fílon, <em>Leg. ad Gai.</em> 200; Jos., <em>Bell.</em> 5, 194, <em>Ant.</em> 1, 338 e outros; Test12Patr; TestSol 6:4 P; Mel., <em>P.</em> 76, 554; 92, 692.) <strong>Estrangeiro, forasteiro</strong>; daí, do ponto de vista judaico, <strong>gentios, pessoas de fora</strong>; como substantivo, <strong>um gentio</strong> (em oposição a <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀνὴρ Ἰουδαῖος\" data-meanings=\"homem judeu\">ἀνὴρ Ἰουδαῖος</span>; compare Jos., <em>Ant.</em> 4, 183): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κολλᾶσθαι ἢ προσέρχεσθαι ἀλλοφύλῳ\" data-meanings=\"associar-se ou aproximar-se de um gentio\">κολλᾶσθαι ἢ προσέρχεσθαι ἀ.</span>, <strong>associar-se com ou aproximar-se de um gentio</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.28\" target=\"_blank\" rel=\"noopener noreferrer\">At 10.28</a>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.19\" target=\"_blank\" rel=\"noopener noreferrer\">13.19</a> D.</p>\n<p class=\"entry-text\">Especialmente, como na LXX, dos <strong>filisteus</strong>, 1 Cl 4:13; ou <strong>amalequitas</strong>, B 12:2; ou <strong>cananeus</strong>, AcPl Ha 8, 13; 15. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ παρεμβολὴ τῶν ἀλλοφύλων\" data-meanings=\"o acampamento dos estrangeiros\">ἡ παρεμβολὴ τῶν ἀ.</span>, <strong>o acampamento dos “estrangeiros”</strong>, 1 Cl 55:4 (compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/JDT.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Jdt 6.1</a>, dos assírios e seus aliados). De cristãos (alguns dos quais seriam israelitas/judeus) em relação aos judeus, Dg 5:17. — M-M. TW.</p>\n</section></article><article id=\"entry-allos-adv-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλλως</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦állōs⟧</span><span class=\"separator\">·</span><span>advérbio de <span class=\"greek\">ἄλλος</span></span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Advérbio de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span> (Homero+; também TestLevi 6:6), <strong>relativo à diferença de maneira ou condição: de outro modo, de outra maneira</strong>, Hs 7:3; 9, 12, 5s.; 9, 13, 2; 9, 16, 2. Sobre o reconhecimento das boas obras: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὰ ἄλλως ἔχοντα κρυβῆναι οὐ δύνανται\" data-meanings=\"as que estão de outro modo não podem permanecer ocultas\">τὰ ἄ. ἔχοντα κρυβῆναι οὐ δύνανται</span>, <strong>se não forem evidentes, não podem, ao fim, permanecer ocultas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.25\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.25</a>. Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλλος\" data-meanings=\"outro\">ἄλλος</span>. — M-M.</p>\n</section></article><article id=\"entry-aloao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλοάω</h1><div class=\"entry-meta\"><span class=\"greek\">fut. ἀλοήσω; 1 aor. ἠλόησα; fut. 3 pl. pass. ἀλοηθήσονται</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦aloáō⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Futuro <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλοήσω\" data-meanings=\"debulharei; trilharei\">ἀλοήσω</span>; 1º aoristo <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἠλόησα\" data-meanings=\"debulhei; trilhei\">ἠλόησα</span>; futuro passivo, 3ª plural, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλοηθήσονται\" data-meanings=\"serão debulhados; serão trilhados\">ἀλοηθήσονται</span> (Aristófanes, Platão, Xenofonte+). <strong>Debulhar, trilhar</strong> (assim Platão, Xenofonte; Teócrito 10, 48; PFrankf 2, 27; 70 [séc. III a.C.]; PLond I, 131, 502 p. 185 e linha 576 p. 187 e outros [78 d.C.]; LXX), trabalho feito sobretudo com bois conduzidos sobre a eira: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.18\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5.18</a> (ambos citam <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/DEU.25.4\" target=\"_blank\" rel=\"noopener noreferrer\">Dt 25.4</a>). Sobre isso, veja I. Benzinger, <em>Hebr. Archäologie</em><sup>2</sup>, 1907, §30, 2; G. Dalman, <em>Arbeit u. Sitte in Palästina III: Von der Ernte z. Mehl usw.</em>, 1933.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὁ ἀλοῶν ἐπ’ ἐλπίδι τοῦ μετέχειν\" data-meanings=\"aquele que debulha o faz na esperança de participar\">ὁ ἀλοῶν (sc. ἀλοᾷ) ἐπ’ ἐλπίδι τοῦ μετέχειν</span>, <strong>aquele que debulha [o faz] na esperança de participar da colheita</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 9.10</a>. — DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλωή\" data-meanings=\"eira; debulha\">ἀλωή</span>. M-M.</p>\n</section></article><article id=\"entry-alogos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλογος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦álogos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Pré-socráticos+; papiros; LXX; PsSol 16:10; TestSol 10:8 C; TestZeb 5:1; ApcEsdr 1:22 p. 25, 17 Tdf.; ApcSed 7:9; Fílon; Josefo.) <span class=\"sense-number\">1.</span> <strong>Relativo à falta de capacidade de raciocínio: irracional, sem razão</strong>, de animais (Crates 11 p. 62, 16 Malherbe): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὡς ἄλογα ζῷα\" data-meanings=\"como animais irracionais\">ὡς ἄ. ζῷα</span>, <strong>como animais irracionais</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.2.12\" target=\"_blank\" rel=\"noopener noreferrer\">2Pe 2.12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 10</a>; GJs 3:2 (assim Demócrito, Fgm. A 116; B 164; Xenofonte, <em>Hiero</em> 7, 3 e outros; Herm. Wr. 1, 11; 10, 19; 22 e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 11.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.14.14\" target=\"_blank\" rel=\"noopener noreferrer\">4Mac 14.14</a>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/4MA.14.18\" target=\"_blank\" rel=\"noopener noreferrer\">18</a>; Fílon, <em>Leg. All.</em> 3, 30 e outros; Jos., <em>C. Ap.</em> 2, 213, <em>Ant.</em> 10, 262; Plutarco, <em>Mor.</em> 493d; Ar. 12:1; Mel., <em>P.</em> 26, 188).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> <strong>Relativo à falta de fundamento ou causa: contrário à razão, absurdo</strong> (Tucídides+; PsSol 16:10 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὀργὴν καὶ θυμὸν ἄλογον\" data-meanings=\"ira e furor irracionais\">ὀργὴν καὶ θυμὸν ἄλογον</span>; Jos., <em>Ant.</em> 1, 24 e outros): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλογόν μοι δοκεῖ\" data-meanings=\"parece-me absurdo\">ἄλογόν μοι δοκεῖ</span>, <strong>parece-me absurdo</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.25.27\" target=\"_blank\" rel=\"noopener noreferrer\">At 25.27</a> (compare BGU 74, 8; OGI 519, 15). — M-M. TW.</p>\n</section></article><article id=\"entry-aloe-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλόη</h1><div class=\"entry-meta\"><span class=\"greek\">ης, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alóē⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Plutarco, <em>Mor.</em> 141f; 693c; Diosc. 3, 22 e outros; PGM 7, 434; PLeid II, X, 12 e 36; PSI 1180, 76; SSol 4:14 v.l. [<span class=\"greek\">αλωθ</span> no texto como representação de <span class=\"hebrew hebrew-term tooltip-trigger\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"אֲהָלוֹת\" data-meanings=\"aloés; madeira aromática\">אֲהָלוֹת</span>; compare <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PSA.45.9\" target=\"_blank\" rel=\"noopener noreferrer\">Sl 45.9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/PRO.7.17\" target=\"_blank\" rel=\"noopener noreferrer\">Pv 7.17</a>; tanto no MT como aqui, provavelmente produto da madeira de ágar, <em>Aquilaria agallocha</em> — <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀγάλλοχον\" data-meanings=\"madeira de ágar; aloe wood\">ἀγάλλοχον</span> — ou <em>A. malaccensis</em>].) <strong>Aloés.</strong></p>\n<p class=\"entry-text\">Em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19.39</a>, <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλόη\" data-meanings=\"aloés\">ἀλόη</span> provavelmente se refere ao suco fortemente aromático e de secagem rápida da <em>aloe vera</em> ou <em>aloe succotrina</em>, aqui misturado com mirra (<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλόη μετὰ σμύρνης\" data-meanings=\"aloés com mirra\">ἀ. w. σμύρνα</span>, PGM 7, 434; SSol 4:14) e usado para embalsamar (Ps.-Calístenes 3, 34, 4: <span class=\"greek\">ἀλόη</span> e <span class=\"greek\">μύρρα</span> [sic] são usados para embalsamar o cadáver de Alexandre; mas, no caso dele, provavelmente se teria usado uma variedade selecionada, como <em>Aquilaria ovata</em>). — M’Clintock-Strong e ISBE, ambos s.v. “Aloes”, apresentam possibilidades. Veja também DELG.</p>\n</section></article><article id=\"entry-hals-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλς</h1><div class=\"entry-meta\"><span class=\"greek\">ἁλός, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦háls⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Homero e outros; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/LEV.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lv 2.13</a>; TestSol 18:34; Fílon, <em>Spec. Leg.</em> 1, 289 e outros; Jos., <em>Ant.</em> 3, 227; veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλας\" data-meanings=\"sal\">ἅλας</span>; DELG <span class=\"greek\">ἅλς</span>.) <strong>Sal.</strong> <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πᾶσα θυσία ἁλὶ ἁλισθήσεται\" data-meanings=\"todo sacrifício será salgado com sal\">πᾶσα θυσία ἁλὶ ἁλισθήσεται</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.49</a> v.l. (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλίζω\" data-meanings=\"salgar\">ἁλίζω</span>). <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"στήλη ἁλός\" data-meanings=\"coluna de sal\">στήλη ἁλός</span>, <strong>coluna de sal</strong>, 1 Cl 11:2 (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/GEN.19.26\" target=\"_blank\" rel=\"noopener noreferrer\">Gn 19.26</a>). Sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.50\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 9.50b</a>, veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἅλας\" data-meanings=\"sal\">ἅλας</span>. — DELG.</p>\n</section></article><article id=\"entry-halykos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἁλυκός</h1><div class=\"entry-meta\"><span class=\"greek\">ή, όν</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦halukós⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Aristófanes, Hipócrates e outros; BGU 14 IV, 22; LXX; DELG 65 <span class=\"greek\">ἅλς</span>.) <strong>Salgado.</strong> De água salgada, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3.11</a> v.l. (veja o aparato de N. e s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πικρός\" data-meanings=\"amargo\">πικρός</span>). Em <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"οὔτε ἁλυκὸν γλυκὺ ποιῆσαι ὕδωρ\" data-meanings=\"nem [pode] uma fonte salgada produzir água doce\">οὔτε ἁλυκὸν γλυκὺ ποιῆσαι ὕδωρ</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">3.12</a>, <span class=\"greek\">ἁ.</span> é geralmente entendido como <strong>fonte salgada</strong> (assim <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλυκίς\" data-meanings=\"fonte salgada\">ἁλυκίς</span>, Estrabão 4, 1, 7): <strong>nem uma fonte salgada pode produzir água doce</strong> (assim também a variante); mas talvez o texto esteja defeituoso (H. Windisch e M. Dibelius ad loc.).</p>\n<p class=\"entry-text\">Teofrasto, <em>HP</em> 4, 3, 5, contrasta <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἁλυκὸν ὕδωρ\" data-meanings=\"água salgada\">ἁλ. ὕδωρ</span> com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ὕδωρ γλυκύ\" data-meanings=\"água doce\">ὕδωρ γλυκύ</span>. Lico, historiador (sécs. IV–III a.C.): 570 Fgm. 8 Jac., sobre o rio Himera, na Sicília: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸν δὲ Ἱμέραν ἐκ μιᾶς πηγῆς σχιζόμενον τὸ μὲν ἁλυκὸν τῶν ῥείθρων ἔχειν, τὸ δὲ πότιμον\" data-meanings=\"o Himera, dividindo-se a partir de uma única fonte, tem uma corrente salgada e a outra potável\">τὸν δὲ Ἱμέραν ἐκ μιᾶς πηγῆς σχιζόμενον τὸ μὲν ἁλυκὸν τῶν ῥείθρων ἔχειν, τὸ δὲ πότιμον</span>, <strong>o Himera, dividindo-se a partir de uma só fonte, tem uma de suas correntes salgada e a outra potável</strong>. — DELG s.v. <span class=\"greek\">ἅλς</span>. M-M.</p>\n</section></article><article id=\"entry-alypetos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλύπητος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alúpētos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\"><strong>Sem tristeza, livre de tristeza</strong> (veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λύπη\" data-meanings=\"tristeza; dor\">λύπη</span>; Sófocles; Teopompo [séc. IV a.C.]: 115 Fgm. 399 Jac., “sinônimo de <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἄλυπος\" data-meanings=\"livre de ansiedade; sem tristeza\">ἄλυπος</span>”): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"εὐφρανθήσεται εἰς τὸν ἀλύπητον αἰῶνα\" data-meanings=\"alegrar-se-á por uma eternidade livre de tristeza\">εὐφρανθήσεται εἰς τὸν ἀ. αἰῶνα</span>, <strong>[a pessoa piedosa] alegrar-se-á por uma eternidade livre de tristeza</strong>, 2 Cl 19:4 (compare Sófocles, <em>Trach.</em> 168 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τὸ λοιπὸν ἤδη ζῆν ἀλυπήτῳ βίῳ\" data-meanings=\"doravante viver uma vida livre de tristeza\">τὸ λοιπὸν ἤδη ζῆν ἀλυπήτῳ βίῳ</span>).</p>\n</section></article><article id=\"entry-alypos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλυπος</h1><div class=\"entry-meta\"><span class=\"greek\">ον</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦álupos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">Veja <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λύπη\" data-meanings=\"tristeza; dor\">λύπη</span>; passivamente, <strong>livre de ansiedade</strong> (assim Sófocles e outros; Xenofonte, <em>Hiero</em> 9, 9; Epicteto; Luciano; Herm. Wr. Fgm. 23, 44 [482, 9 Sc.]; Crates 35 p. 88, 16 Malherbe; ISyriaW 1835; 1851 e outros; PPetr II, xiii, 19, 14 [c. 250 a.C.]; BGU 246, 17 [sécs. II/III d.C.]; TestAbr A 9 p. 87, 6 [Stone p. 22]; Fílon, <em>Cher.</em> 86; Just., <em>D.</em> 117, 3; Ath., <em>R.</em> 78, 1): <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἵνα κἀγὼ ἀλυπότερος ὦ\" data-meanings=\"para que eu também fique menos ansioso\">ἵνα κἀγὼ ἀλυπότερος ὦ</span>, <strong>para que eu também fique menos ansioso</strong> (do que agora = <strong>livre de toda ansiedade</strong>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.2.28\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 2.28</a>. — M-M. TW.</p>\n</section></article><article id=\"entry-halysis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἅλυσις</h1><div class=\"entry-meta\"><span class=\"greek\">εως, ἡ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦hálusis⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀ-\" data-meanings=\"prefixo privativo\">ἀ-</span> privativo + <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λύω\" data-meanings=\"soltar; desatar\">λύω</span>; sobre a aspiração, veja W-S. §5, 10e; Mlt-H. 100.) <span class=\"sense-number\">1.</span> Literalmente, <strong>cadeia, corrente</strong> (Heródoto e outros; SIG<sup>2</sup> 586, 86; 588, 32; PSI 240, 12; PGM 4, 3092; 13, 294; TestSol 15:7; Fílon, <em>Leg. All.</em> 1, 28; Jos., <em>Ant.</em> 3, 170), especialmente <strong>algemas</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.20\" target=\"_blank\" rel=\"noopener noreferrer\">At 28.20</a>.</p>\n<p class=\"entry-text\"><span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δῆσαί τινα ἁλύσει\" data-meanings=\"prender alguém com uma cadeia\">δῆσαί τινα ἁλύσει</span> (desde Tucídides 4, 100, 2; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/LXX/WIS.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Sb 17.16</a>; Jos., <em>Ant.</em> 19, 294), <strong>prender alguém com cadeias</strong>, de uma pessoa possessa, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.3</a>; compare v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">4</a>. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"δεσμεύειν ἁλύσεσιν\" data-meanings=\"prender com correntes\">δεσμεύειν ἁλύσεσιν</span> (com <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πέδαις\" data-meanings=\"grilhões\">πέδαις</span>, como Políbio 3, 82, 8; Dionísio de Halicarnasso 6, 26, 2; 6, 27, 3; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5.4</a>), <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8.29</a>. Cadeias duplas: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.12.6\" target=\"_blank\" rel=\"noopener noreferrer\">At 12.6s.</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">21.33</a>. No começo dos “mil anos”, Satanás será preso com uma corrente, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20.1s.</a>. Do castigo eterno: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"κ[ρατο]ῦντες ἁλύ̣[ς]εις\" data-meanings=\"os que seguravam correntes\">κ[ρατο]ῦντες ἁλύ̣[ς]εις</span>, <strong>os que seguravam correntes</strong>, ApcPt Bodl.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Em sentido geral, <strong>prisão, encarceramento</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"πρεσβεύω ἐν ἁλύσει\" data-meanings=\"sou embaixador em cadeias; como prisioneiro\">πρεσβεύω ἐν ἁλύσει</span>, <strong>em cadeias = como prisioneiro</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ef 6.20</a>; causando desonra, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.1.16\" target=\"_blank\" rel=\"noopener noreferrer\">2Tm 1.16</a>. — DELG. M-M.</p>\n</section></article><article id=\"entry-alysiteles-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἀλυσιτελής</h1><div class=\"entry-meta\"><span class=\"greek\">ές</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦alusitelḗs⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Sócrates 1, 8 p. 22, 21 Malherbe; Hipócrates, Platão, Xenofonte e outros; PSI 441, 21; PCairZen 481, 2 [ambos séc. III a.C.]; PTebt 68, 31 [117/116 a.C.]; Fílon; L. Straub, <em>Philol.</em> 70, 1911, 157–160; termo técnico comercial, <strong>“não cobrir as próprias despesas”</strong>; veja DELG s.v. <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"λύω\" data-meanings=\"soltar; desatar\">λύω</span> e <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"τέλος\" data-meanings=\"fim; resultado; pagamento\">τέλος</span>.) <strong>Sem proveito, improdutivo</strong>: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἀλυσιτελὲς ὑμῖν τοῦτο\" data-meanings=\"isso não vos seria de proveito\">ἀλυσιτελὲς ὑμῖν τοῦτο</span>, <strong>isso não vos seria de proveito</strong>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.17\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13.17</a>. Mas <span class=\"greek\">ἀ.</span> também pode ser usado positivamente no sentido de <strong>prejudicial, nocivo</strong> (Políbio 11, 4, 7; 28, 6, 4 e outros; Fílon, <em>Spec. Leg.</em> 1, 100 <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"ἡ οἴνου χρῆσις ἀλυσιτελής\" data-meanings=\"o uso do vinho é prejudicial\">ἡ οἴνου χρῆσις ἀ.</span>). — M-M.</p>\n</section></article><article id=\"entry-alpha-word-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἄλφα</h1><div class=\"entry-meta\"><span class=\"greek\">τό</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦álpha⟧</span><span class=\"separator\">·</span><span>indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(Platão, <em>Crat.</em> 431e; Aeneas Tact. 1500; 1505; Herodas 3, 22; PCairZen 269, 41; TestSol; PVindobBosw 18, 38; Just., <em>D.</em> 113, 2.) <strong>Alfa.</strong> Veja o verbete <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Α\" data-meanings=\"alfa; primeira letra do alfabeto grego\">Α</span>.</p>\n</section></article><article id=\"entry-halphaios-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\">\n<header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Ἁλφαῖος</h1><div class=\"entry-meta\"><span class=\"greek\">ου, ὁ</span><span class=\"separator\">·</span><span class=\"transliteration\">⟦Halphaîos⟧</span></div></div><div class=\"source-tag\">BDAG</div></header>\n<div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div>\n<p class=\"entry-text\">(<span class=\"greek\">Ἀ</span> em outras edições; hebraico <bdi class=\"hebrew hebrew-term tooltip-trigger\" lang=\"he\" dir=\"rtl\" tabindex=\"0\" data-tooltip-type=\"hebrew\" data-tooltip-label=\"חַלְפִּי\" data-transliteration=\"ḥalpî\" data-meanings=\"Alfeu; nome próprio\">חַלְפִּי</bdi>, compare o siríaco; M. Lidzbarski, <em>Handb. d. nordsem. Epigraphik</em>, 1898, 275; T. Nöldeke, <em>Beiträge z. semit. Sprachwissenschaft</em>, 1904, 98; Procop. Gaz., <em>Ep.</em> 99.) <strong>Alfeu.</strong></p>\n<p class=\"entry-text\"><span class=\"sense-number\">1.</span> Pai de Levi, o cobrador de impostos: <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Λευὶν τὸν τοῦ Ἁλφαίου\" data-meanings=\"Levi, filho de Alfeu\">Λευὶν τὸν τοῦ Ἁ.</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2.14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5.27</a> D; GPt 14:60.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">2.</span> Pai de um dos doze discípulos, chamado <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰάκωβος ὁ τοῦ Ἁλφαίου\" data-meanings=\"Tiago, filho de Alfeu\">Ἰάκωβος ὁ τοῦ Ἁ.</span> para distingui-lo do filho de Zebedeu, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10.3</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3.18</a>; também simplesmente <span class=\"greek greek-term tooltip-trigger\" tabindex=\"0\" data-tooltip-type=\"greek\" data-tooltip-label=\"Ἰάκωβος Ἁλφαίου\" data-meanings=\"Tiago de Alfeu; Tiago, filho de Alfeu\">Ἰ. Ἁλφαίου</span>, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.15\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6.15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 1.13</a>. — Sobre ele e as tentativas de identificar o nº 2 com Clopas, bem como o nº 1 com o nº 2, veja Zahn, <em>Forsch.</em> 6, 1900, 323s.; J. Chapman, <em>JTS</em> 7, 1906, 412ss.; F. Maier, <em>BZ</em> 4, 1906, 164ss.; 255ss.</p>\n</section></article>"};
